'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { Badge } from '@/registry/ndeko/ui/badge';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import {
  USAGE_RESETS_ON,
  WORKSPACE_NAME,
  type Invoice,
  type PlanId,
} from './data';
import { DOLLARS, Invoices } from './invoices';
import { PaymentMethod } from './payment-method';
import { PlanCard } from './plan-card';
import {
  DOWNLOAD_MS,
  DOWNLOADED_MS,
  firstCardErrorOf,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SAVE_CARD_MS,
  SCRIPT,
  SWITCH_MS,
} from './session';
import { SettingsFrame, SettingsSection } from './settings-frame';
import { UsageMeters } from './usage-meters';

/** The address of a saved file lives long enough for the browser to start the download. */
const RELEASE_FILE_AFTER_MS = 1000;

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The file a person saves: the invoice in words, marked as a sample. */
function invoiceTextOf(invoice: Invoice) {
  const total = DOLLARS.format(invoice.amount);
  const lines = [
    WORKSPACE_NAME,
    `Invoice ${invoice.id}, ${invoice.date}`,
    '',
    ...invoice.lines,
    '',
    `Total: ${total}`,
    `Status: ${invoice.status}`,
    '',
    'A sample invoice from a component preview. Illustrative figures.',
  ];
  return lines.join('\n');
}

export default function Settings07() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function toggleChooser() {
    const wasOpen = state.isChoosingPlan;
    act({ type: 'chooserToggled' });
    if (wasOpen) {
      focusLater('[data-change-plan]');
      return;
    }
    focusLater(`[data-plan="${state.planId}"]`);
  }

  function pickPlan(planId: PlanId) {
    act({ type: 'planPicked', planId });
  }

  function finishSwitch() {
    act({ type: 'planSwitched' });
    focusLater('[data-change-plan]');
  }

  function switchPlan() {
    const after = reducer(state, { type: 'switchPressed' });
    act({ type: 'switchPressed' });
    if (after.isSwitchingPlan) {
      schedule(finishSwitch, SWITCH_MS);
    }
  }

  function askCancel() {
    act({ type: 'cancelAsked' });
    focusLater('[data-keep-plan]');
  }

  function keepPlan() {
    act({ type: 'cancelKept' });
    focusLater('[data-plan-end]');
  }

  function confirmCancel() {
    act({ type: 'cancelConfirmed' });
    focusLater('[data-plan-end]');
  }

  function resume() {
    act({ type: 'resumed' });
  }

  function toggleCard() {
    const wasOpen = state.isEditingCard;
    act({ type: 'cardEditToggled' });
    if (wasOpen) {
      focusLater('[data-update-card]');
      return;
    }
    focusLater('[data-card-field="number"]');
  }

  function finishCardSave() {
    act({ type: 'cardSaved' });
    focusLater('[data-update-card]');
  }

  function saveCard() {
    const after = reducer(state, { type: 'cardSavePressed' });
    act({ type: 'cardSavePressed' });
    if (after.isSavingCard) {
      schedule(finishCardSave, SAVE_CARD_MS);
      return;
    }
    const field = firstCardErrorOf(after.cardErrors);
    if (field) {
      focusLater(`[data-card-field="${field}"]`);
    }
  }

  /** Nothing calls a network: the invoice is written in the page and handed to the browser. */
  function saveFile(invoice: Invoice) {
    const text = invoiceTextOf(invoice);
    const blob = new Blob([text], { type: 'text/plain' });
    const address = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = address;
    link.download = `${invoice.id}.txt`;
    link.click();
    schedule(() => URL.revokeObjectURL(address), RELEASE_FILE_AFTER_MS);
  }

  function download(invoice: Invoice) {
    const id = invoice.id;
    const readyAgainAfter = DOWNLOAD_MS + DOWNLOADED_MS;
    act({ type: 'downloadStarted', id });
    schedule(() => {
      act({ type: 'downloadDone', id });
      saveFile(invoice);
    }, DOWNLOAD_MS);
    schedule(() => act({ type: 'downloadFaded', id }), readyAgainAfter);
  }

  /** A change on its way belongs to the round it was asked for in. */
  function replay() {
    clearAll();
    restart();
  }

  return (
    <ClockGate isActive={isInView}>
      <SettingsFrame
        ref={ref}
        title='Billing'
        line={`The plan of ${WORKSPACE_NAME}, what it used this month, its invoices and the card that pays them.`}
        aside={
          <ReplayButton isShown={canReplay} onReplay={replay} label='Replay' />
        }
      >
        <SettingsSection title='Plan'>
          <PlanCard
            state={state}
            pressed={pressed}
            onToggleChooser={toggleChooser}
            onPick={pickPlan}
            onSwitch={switchPlan}
            onAskCancel={askCancel}
            onKeep={keepPlan}
            onConfirmCancel={confirmCancel}
            onResume={resume}
          />
        </SettingsSection>
        <SettingsSection
          title='Usage this month'
          line={
            <span className='flex flex-wrap items-center gap-x-1.5 gap-y-1'>
              {`Resets on ${USAGE_RESETS_ON}`}
              <Badge variant='secondary'>Illustrative</Badge>
            </span>
          }
        >
          <UsageMeters planId={state.planId} used={state.used} />
        </SettingsSection>
        <SettingsSection
          title='Invoices'
          line='Sent to billing@tidewell.example'
        >
          <Invoices
            downloads={state.downloads}
            pressed={pressed}
            onDownload={download}
          />
        </SettingsSection>
        <SettingsSection title='Payment method'>
          <PaymentMethod
            state={state}
            onAction={act}
            onToggle={toggleCard}
            onSave={saveCard}
          />
        </SettingsSection>
        <LiveRegion message={message} />
      </SettingsFrame>
    </ClockGate>
  );
}

'use client';

import { Radio as RadioPrimitive } from '@base-ui/react/radio';
import { RadioGroup as RadioGroupPrimitive } from '@base-ui/react/radio-group';
import { motion } from 'motion/react';
import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import { springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { Wash } from '@/registry/ndeko/ui/wash';

import {
  PLANS,
  RENEWAL_DATE,
  RENEWAL_DAY,
  type Plan,
  type PlanId,
} from './data';
import { isTooSmall, planOf, type BillingState } from './session';
import { SURFACE } from './settings-frame';

export const WHOLE_DOLLARS: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
};

const DOLLARS = new Intl.NumberFormat('en-US', WHOLE_DOLLARS);

type PlanStatus = {
  key: string;
  label: string;
  variant: 'success' | 'warning';
};

function statusOf(state: BillingState): PlanStatus {
  if (state.isCancelling) {
    return {
      key: 'cancelling',
      label: `Cancels on ${RENEWAL_DAY}`,
      variant: 'warning',
    };
  }
  return { key: 'active', label: 'Active', variant: 'success' };
}

function renewalLineOf(state: BillingState, plan: Plan) {
  const isFree = plan.price === 0;
  if (isFree) {
    return `${plan.seats} seats, free, nothing to renew`;
  }
  if (state.isCancelling) {
    return `Ends on ${RENEWAL_DATE}, then moves to Starter. Nothing more is charged`;
  }
  return `${plan.seats} seats · Renews on ${RENEWAL_DATE}`;
}

function priceLineOf(plan: Plan) {
  if (plan.price === 0) {
    return 'Free';
  }
  return `${DOLLARS.format(plan.price)} a month`;
}

function switchLabelsOf(picked: Plan): Record<MorphState, string> {
  return {
    idle: `Switch to ${picked.name}`,
    busy: 'Switching',
    done: 'Switched',
  };
}

function switchStateOf(isSwitching: boolean): MorphState {
  if (isSwitching) {
    return 'busy';
  }
  return 'idle';
}

function tooSmallLineOf(seatsUsed: number) {
  return `${seatsUsed} seats in use`;
}

type PlanChooserProps = {
  state: BillingState;
  onPick: (planId: PlanId) => void;
  onSwitch: () => void;
  onClose: () => void;
};

/** One highlight travels to the plan picked; a plan too small for the team stays in place, dimmed. */
function PlanChooser({ state, onPick, onSwitch, onClose }: PlanChooserProps) {
  const thumbId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const travel = springOf(shouldReduceMotion);
  const picked = planOf(state.pickedPlanId);
  const isSamePlan = state.pickedPlanId === state.planId;
  const seatsUsed = state.used.seats;

  function pick(value: unknown) {
    const plan = PLANS.find((candidate) => candidate.id === value);
    if (plan) {
      onPick(plan.id);
    }
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onClose();
  }

  return (
    <div
      onKeyDown={closeOnEscape}
      className='bg-card/70 dark:bg-foreground/[0.03] flex flex-col gap-3 rounded-lg p-2'
    >
      <RadioGroupPrimitive
        value={state.pickedPlanId}
        onValueChange={pick}
        aria-label='Plans'
        className='flex flex-col gap-1'
      >
        {PLANS.map((plan) => {
          const isPicked = plan.id === state.pickedPlanId;
          const isCurrent = plan.id === state.planId;
          const isBlocked = isTooSmall(plan.id, seatsUsed);
          return (
            <RadioPrimitive.Root
              key={plan.id}
              value={plan.id}
              disabled={isBlocked}
              data-plan={plan.id}
              className='focus-visible:ring-ring/25 relative flex w-full cursor-pointer items-center gap-3 rounded-md px-3 py-2.5 text-start outline-none focus-visible:ring-[3px] data-disabled:cursor-not-allowed data-disabled:opacity-50'
            >
              {isPicked && (
                <motion.span
                  aria-hidden='true'
                  layoutId={thumbId}
                  transition={travel}
                  className='bg-primary/[0.07] hairline-ring ring-primary/30 absolute inset-0 rounded-md'
                />
              )}
              <span className='relative flex min-w-0 flex-1 flex-col gap-0.5'>
                <span className='flex flex-wrap items-center gap-x-2 gap-y-1 text-[13px] font-medium'>
                  {plan.name}
                  {isCurrent && <Badge variant='secondary'>Current</Badge>}
                </span>
                <span className='text-muted-foreground text-xs text-pretty'>
                  {isBlocked && tooSmallLineOf(seatsUsed)}
                  {!isBlocked && `${plan.seats} seats. ${plan.line}`}
                </span>
              </span>
              <span className='relative shrink-0 text-[13px] tabular-nums'>
                {priceLineOf(plan)}
              </span>
            </RadioPrimitive.Root>
          );
        })}
      </RadioGroupPrimitive>
      <div className='flex flex-wrap items-center justify-end gap-2 px-1 pb-1'>
        <Button type='button' variant='ghost' size='sm' onClick={onClose}>
          Close
        </Button>
        <MorphButton
          type='button'
          size='sm'
          state={switchStateOf(state.isSwitchingPlan)}
          labels={switchLabelsOf(picked)}
          disabled={isSamePlan}
          onClick={onSwitch}
        />
      </div>
    </div>
  );
}

type CancelConfirmProps = {
  planName: string;
  pressed: string | null;
  onKeep: () => void;
  onConfirm: () => void;
};

function CancelConfirm({
  planName,
  pressed,
  onKeep,
  onConfirm,
}: CancelConfirmProps) {
  function keepOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onKeep();
  }

  return (
    <div
      role='group'
      aria-label={`Cancel the ${planName} plan`}
      onKeyDown={keepOnEscape}
      className='bg-destructive/[0.06] flex flex-col gap-3 rounded-lg p-3'
    >
      <p className='text-[13px] text-pretty'>
        <span className='font-medium'>{`Cancel the ${planName} plan?`}</span>{' '}
        {`It stays active until ${RENEWAL_DATE}, then the workspace moves to Starter and keeps 5 seats.`}
      </p>
      <div className='flex flex-wrap justify-end gap-2'>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          data-keep-plan
          onClick={onKeep}
        >
          Keep the plan
        </Button>
        <Button
          type='button'
          variant='destructive'
          size='sm'
          onClick={onConfirm}
          className={pressedSolidOf(pressed === 'confirm-cancel')}
        >
          Cancel subscription
        </Button>
      </div>
    </div>
  );
}

function endLabelOf(isCancelling: boolean) {
  if (isCancelling) {
    return 'Resume subscription';
  }
  return 'Cancel subscription';
}

/** Only Cancel opens something: Resume acts at once. */
function endExpandedOf(isCancelling: boolean, isConfirming: boolean) {
  if (isCancelling) {
    return undefined;
  }
  return isConfirming;
}

/** Cancelling is quiet until it is pending; Resume is then the action the card asks for. */
function endLookOf(isCancelling: boolean, pressed: string | null) {
  if (isCancelling) {
    return cn('text-primary-ink', pressedQuietOf(pressed === 'resume'));
  }
  return cn('text-destructive-ink', pressedQuietOf(pressed === 'cancel'));
}

type PlanCardProps = {
  state: BillingState;
  pressed: string | null;
  onToggleChooser: () => void;
  onPick: (planId: PlanId) => void;
  onSwitch: () => void;
  onAskCancel: () => void;
  onKeep: () => void;
  onConfirmCancel: () => void;
  onResume: () => void;
};

/** The one featured surface of the page, so it wears the wash. */
export function PlanCard({
  state,
  pressed,
  onToggleChooser,
  onPick,
  onSwitch,
  onAskCancel,
  onKeep,
  onConfirmCancel,
  onResume,
}: PlanCardProps) {
  const titleId = useId();
  const plan = planOf(state.planId);
  const status = statusOf(state);
  const renewalLine = renewalLineOf(state, plan);
  const isPaid = plan.price > 0;
  const endLabel = endLabelOf(state.isCancelling);

  function pressEnd() {
    if (state.isCancelling) {
      onResume();
      return;
    }
    onAskCancel();
  }

  return (
    <section
      aria-labelledby={titleId}
      className={cn(
        SURFACE,
        'relative isolate flex flex-col gap-4 p-4 @xl:p-5'
      )}
    >
      <Wash />
      <div className='flex flex-wrap items-start gap-x-4 gap-y-3'>
        <div className='flex min-w-0 flex-1 basis-56 flex-col gap-1.5'>
          <div className='flex flex-wrap items-center gap-2'>
            <h3 id={titleId} className='flex text-sm font-medium'>
              <Swap swapKey={plan.name}>{`${plan.name} plan`}</Swap>
            </h3>
            <Badge variant={status.variant}>
              <AnimatedSize as='span' axis='width' contentClassName='flex'>
                <Swap swapKey={status.key}>{status.label}</Swap>
              </AnimatedSize>
            </Badge>
          </div>
          <p className='flex items-baseline gap-1.5'>
            <MotionNumber
              value={plan.price}
              format={WHOLE_DOLLARS}
              className='text-2xl leading-8 font-semibold'
            />
            <span className='text-muted-foreground text-xs'>a month</span>
          </p>
          <p className='text-muted-foreground flex text-xs text-pretty'>
            <Swap swapKey={renewalLine}>{renewalLine}</Swap>
          </p>
        </div>
        <Button
          type='button'
          variant='outline'
          size='sm'
          data-change-plan
          aria-expanded={state.isChoosingPlan}
          onClick={onToggleChooser}
        >
          Change plan
        </Button>
      </div>
      <Fold open={state.isChoosingPlan}>
        <PlanChooser
          state={state}
          onPick={onPick}
          onSwitch={onSwitch}
          onClose={onToggleChooser}
        />
      </Fold>
      {isPaid && (
        <div className='flex flex-col gap-3'>
          <div className='flex flex-wrap items-center justify-between gap-x-4 gap-y-2'>
            <p className='text-muted-foreground text-xs'>
              Prices are illustrative
            </p>
            <Button
              type='button'
              variant='ghost'
              size='sm'
              data-plan-end
              aria-expanded={endExpandedOf(
                state.isCancelling,
                state.isConfirmingCancel
              )}
              onClick={pressEnd}
              className={endLookOf(state.isCancelling, pressed)}
            >
              <AnimatedSize as='span' axis='width' contentClassName='flex'>
                <Swap swapKey={endLabel}>{endLabel}</Swap>
              </AnimatedSize>
            </Button>
          </div>
          <Fold open={state.isConfirmingCancel}>
            <CancelConfirm
              planName={plan.name}
              pressed={pressed}
              onKeep={onKeep}
              onConfirm={onConfirmCancel}
            />
          </Fold>
        </div>
      )}
    </section>
  );
}

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import {
  METERS,
  NEAR_LIMIT_SHARE,
  type Meter,
  type MeterId,
  type PlanId,
} from './data';
import { SURFACE } from './settings-frame';

type Tone = 'calm' | 'near' | 'over';

const FILL_TONE: Record<Tone, string> = {
  calm: 'bg-primary',
  near: 'bg-warning',
  over: 'bg-warning',
};

const NOTE_TONE: Record<Tone, string> = {
  calm: 'text-muted-foreground',
  near: 'text-warning-foreground',
  over: 'text-warning-foreground',
};

function toneOf(used: number, included: number): Tone {
  const share = used / included;
  if (share > 1) {
    return 'over';
  }
  if (share >= NEAR_LIMIT_SHARE) {
    return 'near';
  }
  return 'calm';
}

function formatOf(decimals: number): Intl.NumberFormatOptions {
  return {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  };
}

function quantityOf(value: number, decimals: number) {
  const options = formatOf(decimals);
  const formatter = new Intl.NumberFormat('en-US', options);
  return formatter.format(value);
}

function noteOf(meter: Meter, used: number, included: number, tone: Tone) {
  if (tone === 'over') {
    const extra = used - included;
    const over = quantityOf(extra, meter.decimals);
    return `${over} ${meter.unit} over the plan`;
  }
  const remaining = included - used;
  const left = quantityOf(remaining, meter.decimals);
  if (tone === 'near') {
    return `Near the limit: ${left} ${meter.unit} left`;
  }
  return `${left} ${meter.unit} left`;
}

/** The bar stops at its end: what goes past the plan is said in words under it. */
function fillStyleOf(used: number, included: number) {
  const ratio = used / included;
  const share = Math.min(ratio, 1);
  return { transform: `scaleX(${share})` };
}

type MeterRowProps = {
  meter: Meter;
  used: number;
  included: number;
};

function MeterRow({ meter, used, included }: MeterRowProps) {
  const tone = toneOf(used, included);
  const note = noteOf(meter, used, included, tone);
  const includedText = quantityOf(included, 0);
  const usedText = quantityOf(used, meter.decimals);
  const valueNow = Math.min(used, included);

  return (
    <li className='flex flex-col gap-2'>
      <p className='flex flex-wrap items-baseline justify-between gap-x-3'>
        <span className='text-[13px] font-medium'>{meter.label}</span>
        <span className='text-[13px] tabular-nums'>
          <MotionNumber value={used} format={formatOf(meter.decimals)} />
          <span className='text-muted-foreground'>
            {` of ${includedText} ${meter.unit}`}
          </span>
        </span>
      </p>
      <div
        role='meter'
        aria-label={meter.label}
        aria-valuemin={0}
        aria-valuemax={included}
        aria-valuenow={valueNow}
        aria-valuetext={`${usedText} of ${includedText} ${meter.unit}`}
        className='bg-foreground/10 h-1.5 overflow-hidden rounded-full'
      >
        <span
          style={fillStyleOf(used, included)}
          className={cn(
            'block h-full origin-left rounded-full transition-[transform,background-color] duration-500 ease-(--ease-out-strong) rtl:origin-right',
            FILL_TONE[tone]
          )}
        />
      </div>
      <p className={cn('flex text-xs tabular-nums', NOTE_TONE[tone])}>
        <Swap swapKey={tone}>{note}</Swap>
      </p>
    </li>
  );
}

type UsageMetersProps = {
  planId: PlanId;
  used: Record<MeterId, number>;
};

/** What the plan includes follows the plan: a change of plan moves every bar. */
export function UsageMeters({ planId, used }: UsageMetersProps) {
  return (
    <ul className={cn(SURFACE, 'flex flex-col gap-5 p-4 @xl:p-5')}>
      {METERS.map((meter) => (
        <MeterRow
          key={meter.id}
          meter={meter}
          used={used[meter.id]}
          included={meter.included[planId]}
        />
      ))}
    </ul>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { DownloadIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/registry/ndeko/ui/table';

import { INVOICES, type Invoice, type InvoiceStatus } from './data';
import type { DownloadStatus } from './session';
import { SURFACE } from './settings-frame';

export const DOLLARS = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
});

const DOWNLOAD_LABELS: Record<MorphState, string> = {
  idle: 'Download',
  busy: 'Preparing',
  done: 'Downloaded',
};

const MORPH_OF: Record<DownloadStatus, MorphState> = {
  idle: 'idle',
  busy: 'busy',
  done: 'done',
};

const STATUS_LABEL: Record<InvoiceStatus, string> = {
  paid: 'Paid',
  refunded: 'Refunded',
};

const STATUS_VARIANT: Record<InvoiceStatus, 'success' | 'secondary'> = {
